#!/usr/bin/env python3
"""Verified launcher for native pre-postprocess God of War frame capture."""
from __future__ import annotations
import base64
import hashlib
import os
import subprocess
import sys
import tempfile
import zlib
EXPECTED_SHA256 = "9fb7dc8c7b34024daabc54a04a0d3d32455b4f9b6a029e062be9ebcdff7a0ac9"
PAYLOAD = (
    ''
    ''
    ''
    ''
)
def main():
    source=zlib.decompress(base64.b64decode(PAYLOAD,validate=True))
    actual=hashlib.sha256(source).hexdigest()
    if actual!=EXPECTED_SHA256:
        raise RuntimeError("SAFE_STOP: pinned game-only diagnostic checksum mismatch: "+actual)
    print("GOW_NATIVE_CAPTURE=REUSE_EXISTING_ISOLATED_BINARY_NO_BUILD",flush=True)
    with tempfile.TemporaryDirectory(prefix="gow-raw-verified-") as tmp:
        path=os.path.join(tmp,"diagnose-gow-game-only.py")
        compile(source,path,"exec")
        with open(path,"wb") as f: f.write(source)
        return subprocess.run([sys.executable,path,*sys.argv[1:]],check=False).returncode
if __name__=="__main__":
    try:sys.exit(main())
    except Exception as e:
        print("SAFE_STOP_WRAPPER="+str(e),file=sys.stderr)
        sys.exit(1)
